def union_intervals(intervals):
    # Normalize each interval into a list of (lo, hi, left_closed, right_closed)
    # Ignore empty intervals.
    norm = []
    for lo, hi, lc, rc in intervals:
        if lo == hi:
            if lc and rc:
                norm.append((lo, hi, True, True))
            # else empty, ignore
        else:
            norm.append((lo, hi, lc, rc))

    if not norm:
        return []

    # Sort by lo, then by hi, then prefer closed left first (doesn't matter much)
    norm.sort(key=lambda x: (x[0], x[1], not x[2]))

    result = []
    cur_lo, cur_hi, cur_lc, cur_rc = norm[0]

    for lo, hi, lc, rc in norm[1:]:
        # Determine if current interval can be merged with the next one.
        # They can merge if:
        # - lo < cur_hi (overlap)
        # - lo == cur_hi and (cur_rc or lc) (touching with at least one closed)
        can_merge = False
        if lo < cur_hi:
            can_merge = True
        elif lo == cur_hi:
            if cur_rc or lc:
                can_merge = True

        if can_merge:
            # Merge: new hi is max of cur_hi and hi
            if hi > cur_hi:
                cur_hi = hi
                cur_rc = rc
            elif hi == cur_hi:
                # If equal, right closed if either is closed
                cur_rc = cur_rc or rc
            # left endpoint stays cur_lo, cur_lc
        else:
            result.append((cur_lo, cur_hi, cur_lc, cur_rc))
            cur_lo, cur_hi, cur_lc, cur_rc = lo, hi, lc, rc

    result.append((cur_lo, cur_hi, cur_lc, cur_rc))
    return result
